    {
      "dependency_id": "additional.home_requirements",
      "evidence": {
        "quote": "which comply with the fund’s home jurisdiction requirements",
        "unit_id": "d97b56331f41a.u5.840"
      },
      "needed_for_control": true,
      "title_or_locator": "Applicable fund home-jurisdiction requirements; specific instruments not identified"
    },
    {
      "dependency_id": "additional.existing_process",
      "evidence": {
        "quote": "in accordance with the existing approval or authorisation process",
        "unit_id": "d97b56331f41a.u10.1809"
      },
      "needed_for_control": true,
      "title_or_locator": "Existing SFC approval or authorisation process applicable to pending applications received before 28 November 2025"
    }
  ],
  "claims": [
    {
      "action": "Apply the measures to certain post-authorisation matters",
      "actor": "SFC",
      "claim_id": "c1",
      "conditions": ["The fund falls within this circular’s definition of UCITS funds."],
      "evidence": [
        {
          "quote": "The SFC has further streamlined measures for processing certain post-authorisation matters for UCITS funds1",
          "unit_id": "d97b56331f41a.u1.190"
        },
        {
          "quote": "The key streamlined measures cover the following post-authorisation matters:",
          "unit_id": "d97b56331f41a.u3.575"
        }
      ],
      "exceptions": [],
      "kind": "SCOPE",
      "modality": "DESCRIPTIVE",
      "relevance": "CONTROL",
      "statement": "The streamlining concerns certain post-authorisation matters for UCITS funds.",
      "temporal": [],
      "uncertainty": []
    },
    {
      "action": "Define UCITS funds for this circular",
      "actor": "Circular",
      "claim_id": "c2",
      "conditions": [],
      "evidence": [
        {
          "quote": "For this circular, UCITS funds means (i) Undertakings for Collective Investment in Transferable Securities (UCITS) domiciled in France, Luxembourg, Ireland and the Netherlands, and (ii) collective investment schemes domiciled in the United Kingdom authorised as UK UCITS.",
          "unit_id": "d97b56331f41a.u17.2556"
        }
      ],
      "exceptions": [],
      "kind": "DEFINITION",
      "modality": "DESCRIPTIVE",
      "relevance": "CONTROL",
      "statement": "UCITS funds means UCITS domiciled in France, Luxembourg, Ireland or the Netherlands, and UK-domiciled collective investment schemes authorised as UK UCITS.",
      "temporal": [],
      "uncertainty": []
    },
    {
      "action": "Facilitate changes subject to home-regulator supervision",
      "actor": "SFC",
      "claim_id": "c3",
      "conditions": [],
      "evidence": [
        {
          "quote": "These measures aim at facilitating UCITS funds in implementing changes that are subject to their home regulator’s supervision",
          "unit_id": "d97b56331f41a.u1.190"
        }
      ],
      "exceptions": [],
      "kind": "SCOPE",
      "modality": "DESCRIPTIVE",
      "relevance": "CONTROL",
      "statement": "The stated purpose is to facilitate UCITS fund changes subject to home-regulator supervision.",
      "temporal": [],
      "uncertainty": ["The introductory purpose statement does not expressly establish a separate approval condition beyond the specific home-jurisdiction compliance condition."]
    },
    {
      "action": "Remove the prior SFC approval requirement",
      "actor": "SFC",
      "claim_id": "c4",
      "conditions": [
        "The change is a material change in investment objectives, policies or restrictions of an in-scope UCITS fund.",
        "The change complies with the fund’s home-jurisdiction requirements."
      ],
      "evidence": [
        {
          "quote": "Removing the SFC’s requirement on prior approval for material changes in investment objectives, policies and restrictions which comply with the fund’s home jurisdiction requirements, except for changes that involve novel or complex product features and/or which may have local policy implications.",
          "unit_id": "d97b56331f41a.u5.840"
        }
      ],
      "exceptions": [
        "Changes involving novel or complex product features.",
        "Changes which may have local policy implications.",
        "Pending pre-Effective Date applications remain subject to the existing process."
      ],
      "kind": "PERMISSION",
      "modality": "MAY",
      "relevance": "CONTROL",
      "statement": "Subject to the exceptions and application transition, qualifying material investment changes may proceed without prior SFC approval under the removed requirement.",
      "temporal": ["Effective 28 November 2025."],
      "uncertainty": ["Failure to satisfy home-jurisdiction requirements does not receive this removal; the excerpt does not independently state the complete approval rule for such changes."]
    },
    {
      "action": "Exclude novel or complex product changes from the removal",
      "actor": "SFC",
      "claim_id": "c5",
      "conditions": ["The change involves novel or complex product features."],
      "evidence": [
        {
          "quote": "except for changes that involve novel or complex product features and/or which may have local policy implications.",
          "unit_id": "d97b56331f41a.u5.840"
        }
      ],
      "exceptions": [],
      "kind": "EXCEPTION",
      "modality": "DESCRIPTIVE",
      "relevance": "CONTROL",
      "statement": "Changes involving novel or complex product features are excepted from removal of the prior SFC approval requirement.",
      "temporal": [],
      "uncertainty": ["Novel and complex product features are not defined in the supplied text."]
    },
    {
      "action": "Exclude changes with potential local policy implications from the removal",
      "actor": "SFC",
      "claim_id": "c6",
      "conditions": ["The change may have local policy implications."],
      "evidence": [
        {
          "quote": "except for changes that involve novel or complex product features and/or which may have local policy implications.",
          "unit_id": "d97b56331f41a.u5.840"
        }
      ],
      "exceptions": [],
      "kind": "EXCEPTION",
      "modality": "DESCRIPTIVE",
      "relevance": "CONTROL",
      "statement": "Potential local policy implications independently except a change from the removal, whether or not it involves novel or complex product features.",
      "temporal": [],
      "uncertainty": ["Local policy implications and their assessment threshold are not defined in the supplied text."]
    },
    {
      "action": "Give effect to streamlined measures",
      "actor": "SFC",
      "claim_id": "c7",
      "conditions": [],
      "evidence": [
        {
          "quote": "and will take immediate effect.",
          "unit_id": "d97b56331f41a.u1.190"
        },
        {
          "quote": "The streamlined measures set out in the relevant FAQs will take effect on 28 November 2025 (Effective Date).",
          "unit_id": "d97b56331f41a.u9.1696"
        }
      ],
      "exceptions": ["The separate transition provision governs specified existing applications."],
      "kind": "TIME",
      "modality": "DESCRIPTIVE",
      "relevance": "CONTROL",
      "statement": "The implementation provision fixes the Effective Date at 28 November 2025; the introduction also describes the measures as taking immediate effect.",
      "temporal": ["28 November 2025 (Effective Date).", "Immediate effect in the introduction."],
      "uncertainty": ["The supplied units do not state the circular’s issuance date, so the relationship between 'immediate' and the specified date cannot independently be verified."]
    },
    {
      "action": "Process existing applications under the existing process",
      "actor": "SFC",
      "claim_id": "c8",
      "conditions": [
        "The SFC received the application before 28 November 2025.",
        "No approval or authorisation has been granted."
      ],
      "evidence": [
        {
          "quote": "Existing applications received by the SFC before the Effective Date for which no approval or authorisation has been granted will be processed by the SFC in accordance with the existing approval or authorisation process.",
          "unit_id": "d97b56331f41a.u10.1809"
        }
      ],
      "exceptions": [],
      "kind": "EXCEPTION",
      "modality": "DESCRIPTIVE",
      "relevance": "CONTROL",
      "statement": "Pending applications received before the Effective Date remain under the existing approval or authorisation process.",
      "temporal": ["Receipt before 28 November 2025.", "No approval or authorisation yet granted."],
      "uncertainty": ["The existing process is not supplied."]
    },
    {
      "action": "Align post-authorisation notification requirements",
      "actor": "SFC",
      "claim_id": "c9",
      "conditions": ["In-scope UCITS post-authorisation notifications."],
      "evidence": [
        {
          "quote": "To align the SFC’s notification requirements with the fund’s home jurisdiction requirements, including the notice periods and content requirements.",
          "unit_id": "d97b56331f41a.u6.1221"
        }
      ],
      "exceptions": [],
      "kind": "SCOPE",
      "modality": "DESCRIPTIVE",
      "relevance": "CONTROL",
      "statement": "The streamlining also aligns notification requirements, including notice periods and content, with home-jurisdiction requirements.",
      "temporal": [],
      "uncertainty": ["Actual notification duties and periods are not specified; removal of prior approval does not establish their removal."]
    },
    {
      "action": "Specify the measures and supporting compliance materials",
      "actor": "SFC",
      "claim_id": "c10",
      "conditions": [],
      "evidence": [
        {
          "quote": "The SFC has updated and published on its website relevant FAQs2 , including a revamped FAQ on SFC Authorization of UCITS Funds to facilitate UCITS fund managers in navigating post-authorisation compliance matters, as well as related forms and checklists3 .",
          "unit_id": "d97b56331f41a.u7.1419"
        },
        {
          "quote": "The streamlined measures set out in the relevant FAQs",
          "unit_id": "d97b56331f41a.u9.1696"
        },
        {
          "quote": "2 Please refer to https://www.sfc.hk/en/faqs/Publicly-offered-investment-products",
          "unit_id": "d97b56331f41a.u18.2831"
        },
        {
          "quote": "3 Please refer to https://www.sfc.hk/en/Forms/products/Investment-products-Forms-and-checklists",
          "unit_id": "d97b56331f41a.u19.2914"
        }
      ],
      "exceptions": [],
      "kind": "DEPENDENCY",
      "modality": "DESCRIPTIVE",
      "relevance": "CONTROL",
      "statement": "Relevant updated FAQs set out the measures, with related forms and checklists supporting post-authorisation compliance.",
      "temporal": [],
      "uncertainty": ["These external materials are not supplied and may contain operational qualifications."]
    },
    {
      "action": "Continue post-vetting scheme changes and revised documents",
      "actor": "SFC",
      "claim_id": "c11",
      "conditions": ["Scheme changes and related revised documents filed with the SFC."],
      "evidence": [
        {
          "quote": "The SFC will continue to conduct post-vetting of scheme changes (including those not subject to the SFC’s prior approval) and related revised documents filed with the SFC.",
          "unit_id": "d97b56331f41a.u12.2069"
        }
      ],
      "exceptions": [],
      "kind": "SCOPE",
      "modality": "DESCRIPTIVE",
      "relevance": "CONTROL",
      "statement": "SFC post-vetting continues, including for changes not subject to prior approval and related revised documents filed with it.",
      "temporal": ["Continuing post-vetting."],
      "uncertainty": ["This sentence does not specify a standalone filing duty or filing deadline."]
    },
    {
      "action": "Make follow-up enquiries or take appropriate regulatory actions",
      "actor": "SFC",
      "claim_id": "c12",
      "conditions": ["In case of non-compliance."],
      "evidence": [
        {
          "quote": "It may make follow-up enquiries and/or take appropriate regulatory actions in case of non-compliance to ensure investor protection.",
          "unit_id": "d97b56331f41a.u12.2069"
        }
      ],
      "exceptions": [],
      "kind": "PERMISSION",
      "modality": "MAY",
      "relevance": "CONTROL",
      "statement": "The SFC may make follow-up enquiries and/or take appropriate regulatory actions in case of non-compliance.",
      "temporal": [],
      "uncertainty": []
    }
  ],
  "uncertainties": [
    "The supplied dependency identifiers have no explicit title mapping; their association with footnotes 2 and 3 follows their supplied order.",
    "The relevant FAQs, forms, checklists, applicable home-jurisdiction requirements and existing approval process are not supplied.",
    "The circular supplies no definitions or concrete assessment criteria for novel or complex product features or potential local policy implications.",
    "Home-regulator supervision appears in the purpose statement; whether it adds an independent condition requires the relevant FAQs.",
    "The excerpt removes a specified approval requirement subject to exceptions; it does not establish that every change outside the removal necessarily requires approval under every applicable rule."
  ],
